@Suppress("UNCHECKED_CAST")
inline fun <reified T : Any> getServiceManager(): RpcServiceManager<T> = when (T::class) {
    rpc.AppService::class -> rpc.AppServiceManager as RpcServiceManager<T>
    else -> throw IllegalArgumentException("Unknown service ${T::class}")
}

fun getAllServiceManagers(): List<RpcServiceManager<*>> = listOf(
    rpc.AppServiceManager,
)

fun getServiceManagers(vararg kclass: KClass<*>): List<RpcServiceManager<*>> {
    return kclass.map {
        when (it) {
            rpc.AppService::class -> rpc.AppServiceManager
            else -> throw IllegalArgumentException("Unknown service ${it.simpleName}")
        }
    }
}

public expect inline fun <reified T : Any> getService(
